input.query:
fetch spans, from: now()-7d, to: now()
| filter isNotNull(gen_ai.provider.name) OR isNotNull(gen_ai.request.model)
| summarize {
    total_requests = count(),
    total_input_tokens = sum(coalesce(gen_ai.usage.prompt_tokens, gen_ai.usage.input_tokens, 0)),
    total_output_tokens = sum(coalesce(gen_ai.usage.completion_tokens, gen_ai.usage.output_tokens, 0)),
    avg_latency_ms = avg(duration / 1000000),
    error_count = countIf(otel.status_code == "ERROR")
  }, by: { provider = gen_ai.provider.name, model = gen_ai.request.model }
| sort total_requests desc

fetch spans, from: now()-14d, to: now()
| filter isNotNull(gen_ai.provider.name) OR isNotNull(gen_ai.request.model)
| summarize {
    requests = count(),
    tokens = sum(coalesce(gen_ai.usage.prompt_tokens, gen_ai.usage.input_tokens, 0) + coalesce(gen_ai.usage.completion_tokens, gen_ai.usage.output_tokens, 0))
  }, by: { day = bin(start_time, 1d) }
| sort day asc
